import { isRecord } from "./is-record.js";
export const DEFINITION_BRAND_FIELD = "__agentServe";
const DEFINITION_KINDS = new Set([
    "agent",
    "instructions",
    "tool",
    "skill",
    "extension",
    "disabled-tool",
    "disabled-connection",
    "disabled",
    "connection",
    "channel",
    "http-channel",
    "schedule",
    "reminder",
    "hook",
    "eval",
    "storage",
    "artifacts",
]);
function isDefinitionKind(value) {
    return DEFINITION_KINDS.has(value);
}
export function brandDefinition(kind, definition) {
    return { ...definition, [DEFINITION_BRAND_FIELD]: kind };
}
export function getDefinitionKind(value) {
    if (!isRecord(value)) {
        return undefined;
    }
    const kind = value[DEFINITION_BRAND_FIELD];
    if (typeof kind !== "string" || !isDefinitionKind(kind)) {
        return undefined;
    }
    return kind;
}
export function isDefinitionOfKind(value, kind) {
    return getDefinitionKind(value) === kind;
}
